member.example:
Příklad vytvoření vlastního modulu:


-> v souboru GTask1.cs

public class GTask1 : GTask
{
	// ...

	// zde je reakce na spuštění úlohy
	private void GTask1_TaskRun(object sender, System.EventArgs e)
	{
		GMyTab1 l_oTab = new GMyTab1();
		m_oWin = new GWin(l_oTab, "Seznam");
		this.WinList.AddModalWin(m_oWin, "Kartotéka majetku");
	}
}



-> v souboru GTask2.cs

public class GTask2 : GTask
{
	// ...

	// zde je reakce na spuštění úlohy
	private void GTask2_TaskRun(object sender, System.EventArgs e)
	{
		GMyTab2 l_oTab = new GMyTab2();
		m_oWin = new GWin(l_oTab, "Seznam");
		this.WinList.AddModalWin(m_oWin, "Evidence dokladů");
	}
}



-> v souboru GMyModuleForm.cs

public class GMyModuleForm : GModuleForm
{
	// ...
	public GMyModuleForm()
	{
		// This call is required by the Windows Form Designer.
		InitializeComponent();
	}

    private void InitializeComponent()	
    {
		// ...
		// ...
		this.Load += new System.EventHandler(this.GMyModuleForm_Load);
	} 

    private void GMyModuleForm_Load(object sender, System.EventArgs e) 
	{	
		// vložení dvou úloh do modulu
		Module.TaskList.Add(new GTask1());	// vložení úlohy je 1 řádek kódu !	
		Module.TaskList.Add(new GTask2());	// chování úlohy je celé definováno ve třídě úlohy
	} 

	// ...
}

