member.example:
Příklad použití komponenty	




...
protected Gordic.WinForms.Gui.GLabelPanel m_oGLabelPanel = new GLabelPanel();
// definice ve WinForm formuláři 
...
private void InitializeComponent()
{ 
	this.m_oGLabelPanel = new Gordic.WinForms.GLabelPanel.GLabelPanel();

	this.m_oGLabelPanel.BackColor = System.Drawing.SystemColors.Control;
	this.m_oGLabelPanel.Cursor = System.Windows.Forms.Cursors.Default;
	this.m_oGLabelPanel.DistanceLabels = 40;
	this.m_oGLabelPanel.DistanceNameValue = 20;
	this.m_oGLabelPanel.DockPadding.All = 2;
	this.m_oGLabelPanel.LabelFontSize = 8;
	this.m_oGLabelPanel.Labels = new string[] 
		{
			"IČO",
			"Firma",
			"Datum"};
	this.m_oGLabelPanel.Location = new System.Drawing.Point(48, 32);
	this.m_oGLabelPanel.Name = "m_oGLabelPanel";
	this.m_oGLabelPanel.Size = new System.Drawing.Size(450, 25);
	this.m_oGLabelPanel.TabIndex = 0;
	this.m_oGLabelPanel.XPosition = 4;
	this.m_oGLabelPanel.YPosition = 4;			
	...
	this.Controls.Add(this.m_oGLabelPanel);
	...
}



Pokud chcete nastavit nebo změnit hodnotu vedle popisku



	...
	this.m_oGLabelPanel["Firma"] = "Gordic";			
	... 
}

Vložení modálního okna (do úlohy):


// GMyTab je nějaká karta (zděděno z GTab)
GWin l_oWin = new GWin( new GMyTab(), "Seznam" );	
Win.AddModalWin( l_oWin, "Kartotéka majetku" );

Vložení odděleného okna (do úlohy):


// GMyTab je nějaká karta (zděděno z GTab)
GWin l_oWin = new GWin( new GMyTab(), "Seznam" );	
Win.AddSeparateWin( l_oWin, "Kartotéka majetku" );
